script:
(function () {
  'use strict';
  // Dealer financing vs a credit union loan for the same car.
  //   Taxable amount = price - trade-in value (when the trade-in credit box is ticked), never below 0.
  //   Base amount = price - down payment - trade-in + owed on trade-in + sales tax + title/registration fees
  //   (both offers finance tax and fees).
  //   Dealer loan = base + add-ons rolled into the dealer loan.
  //   Credit union loan = base + add-ons bought through the credit union - any rebate you only get when
  //   you don't take the dealer's financing. Credit union fees are paid at signing.
  //   Payment: M = L x i / (1 - (1 + i)^-n), i = APR / 12 (M = L / n at 0%).
  //   Total cost = down payment + upfront fees + all loan payments (same basis for both offers).
  //   Rate markup cost = dealer-loan interest at the quoted rate - interest at the lender's buy rate.
  //   Add-on cost = add-ons + the extra interest they cause (payments with add-ons - payments without).
  //   Break-even dealer rate: the dealer rate at which both totals are equal, by bisection on 0-40%.
  // Verified in Node (scratchpad tests/auto5): $35,000 car, $4,000 down, 6% tax ($2,100), $800 fees ->
  //   base $33,900; dealer $36,400 at 7.9% for 72 months = $636.43/mo (closed form); credit union
  //   $33,900 at 6% for 60 months = $655.38/mo; totals $49,823.26 vs $43,347.92 (with $25 fee); markup
  //   7.9% vs 6.4% = $1,892.47 and add-on cost $3,147.20, both equal to closed-form payment gaps x 72;
  //   at the break-even dealer rate (2.60%) both totals match to the cent;
  //   0% rates give L / n; no NaN on blank or negative input.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });

  function el(id) { return document.getElementById(id); }
  function setText(id, text) { el(id).textContent = text; }

  function read(id, blankAsZero) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAsZero ? 0 : NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function monthlyPayment(principal, annualRate, months) {
    if (months <= 0 || principal <= 0) return 0;
    var i = annualRate / 12;
    if (i === 0) return principal / months;
    return principal * i / (1 - Math.pow(1 + i, -months));
  }

  function offer(loan, rate, months, upfront) {
    var pay = monthlyPayment(loan, rate, months), paid = loan > 0 ? pay * months : 0;
    return { loan: Math.max(0, loan), payment: pay, paid: paid, interest: Math.max(0, paid - Math.max(0, loan)), upfront: upfront };
  }

  function breakEvenRate(loan, months, target) {
    // Total cost rises with the rate; find the dealer rate giving the same total as the credit union.
    var lo = 0, hi = 0.4;
    if (monthlyPayment(loan, lo, months) * months > target || monthlyPayment(loan, hi, months) * months < target) return null;
    for (var k = 0; k < 80; k++) {
      var mid = (lo + hi) / 2;
      if (monthlyPayment(loan, mid, months) * months > target) hi = mid; else lo = mid;
    }
    return (lo + hi) / 2;
  }

  function clearResults() {
    ['dcVerdict', 'dcDealerTotal', 'dcCuTotal', 'dcDealerPay', 'dcCuPay', 'dcMarkupCost', 'dcAddonCost', 'dcBreakEven'].forEach(function (id) { setText(id, '–'); });
    setText('dcVerdictLabel', 'Cheaper offer');
    el('dcMarkupBox').hidden = true;
    el('dcBreakdown').innerHTML = '';
  }

  function update() {
    var price = read('dcPrice'), down = read('dcDown', true), trade = read('dcTrade', true), owed = read('dcOwed', true),
        taxRate = read('dcTaxRate', true), fees = read('dcFees', true),
        dRate = read('dcDealerRate'), dTerm = read('dcDealerTerm'), addons = read('dcAddons', true), buyRaw = String(el('dcBuyRate').value).trim(),
        cRate = read('dcCuRate'), cTerm = read('dcCuTerm'), cFee = read('dcCuFee', true), cAddons = read('dcCuAddons', true),
        rebate = read('dcRebate', true), tradeCredit = el('dcTradeCredit').checked;
    var buyRate = buyRaw === '' ? null : Number(buyRaw);
    var error = el('dcError'), msg = '';
    if (isNaN(price) || price <= 0) msg = 'Enter a vehicle price greater than $0.';
    else if (isNaN(dRate) || dRate < 0 || dRate > 40) msg = 'Enter a dealer rate from 0% to 40%.';
    else if (isNaN(cRate) || cRate < 0 || cRate > 40) msg = 'Enter a credit union rate from 0% to 40%.';
    else if ([dTerm, cTerm].some(function (t) { return isNaN(t) || t < 1 || t > 120 || t % 1 !== 0; })) msg = 'Enter loan terms of 1 to 120 whole months.';
    else if (buyRate !== null && (!isFinite(buyRate) || buyRate < 0 || buyRate > 40)) msg = 'Enter a buy rate from 0% to 40%, or leave it blank.';
    else if ([down, trade, owed, taxRate, fees, addons, cFee, cAddons, rebate].some(function (v) { return isNaN(v) || v < 0; })) msg = 'Amounts and rates cannot be negative.';
    else if (taxRate > 20) msg = 'Enter a sales tax rate of 20% or less.';
    if (msg) { error.hidden = false; error.textContent = msg; clearResults(); return; }

    var taxable = Math.max(0, price - (tradeCredit ? trade : 0));
    var salesTax = taxable * taxRate / 100;
    var base = price - down - trade + owed + salesTax + fees;
    if (base <= 0.005) { error.hidden = false; error.textContent = 'Your down payment and trade-in cover the full cost, so there is nothing to finance.'; clearResults(); return; }
    error.hidden = true;
    error.textContent = '';

    var dl = offer(base + addons, dRate / 100, dTerm, down);
    var cuLoan = base + cAddons - rebate;
    if (cuLoan <= 0.005) { error.hidden = false; error.textContent = 'The rebate is larger than the credit union loan. Lower the rebate or the down payment.'; clearResults(); return; }
    var cl = offer(cuLoan, cRate / 100, cTerm, down + cFee);
    var dTotal = dl.upfront + dl.paid, cTotal = cl.upfront + cl.paid, diff = dTotal - cTotal;
    if (Math.abs(diff) < 0.5) { setText('dcVerdictLabel', 'Cheaper offer'); setText('dcVerdict', 'About the same'); }
    else { setText('dcVerdictLabel', diff > 0 ? 'Credit union saves you' : 'Dealer financing saves you'); setText('dcVerdict', money.format(Math.abs(diff))); }
    setText('dcDealerTotal', money.format(dTotal));
    setText('dcCuTotal', money.format(cTotal));
    setText('dcDealerPay', money.format(dl.payment));
    setText('dcCuPay', money.format(cl.payment));

    var noAddons = offer(base, dRate / 100, dTerm, 0);
    setText('dcAddonCost', money.format(dl.paid - noAddons.paid));
    if (buyRate !== null && buyRate < dRate) {
      var atBuy = offer(base + addons, buyRate / 100, dTerm, 0);
      el('dcMarkupBox').hidden = false;
      setText('dcMarkupCost', money.format(dl.paid - atBuy.paid));
    } else {
      el('dcMarkupBox').hidden = true;
      setText('dcMarkupCost', '–');
    }
    var be = breakEvenRate(dl.loan, dTerm, cTotal - dl.upfront);
    setText('dcBreakEven', be === null ? (dl.upfront + monthlyPayment(dl.loan, 0, dTerm) * dTerm > cTotal ? 'None: even 0% costs more' : 'Above 40%') : (be * 100).toFixed(2) + '%');

    var rows = [
      ['Amount financed', money.format(dl.loan), money.format(cl.loan)],
      ['Interest rate (APR)', dRate.toFixed(2) + '%', cRate.toFixed(2) + '%'],
      ['Term', dTerm + ' months', cTerm + ' months'],
      ['Monthly payment', money.format(dl.payment), money.format(cl.payment)],
      ['Add-ons in the loan', money.format(addons), money.format(cAddons)],
      ['Rebate applied', '—', rebate > 0 ? '−' + money.format(rebate) : '—'],
      ['Cash at signing', money.format(dl.upfront), money.format(cl.upfront)],
      ['Total interest', money.format(dl.interest), money.format(cl.interest)],
      ['Total of loan payments', money.format(dl.paid), money.format(cl.paid)],
      ['Total cost', money.format(dTotal), money.format(cTotal)]
    ];
    el('dcBreakdown').innerHTML = rows.map(function (r, idx) {
      var strong = idx === rows.length - 1 ? ' class="font-semibold"' : '';
      return '<tr' + strong + '><th scope="row">' + r[0] + '</th><td>' + r[1] + '</td><td>' + r[2] + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('dcForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
